// a binary output. It's a generated lookup table, expanded inline here to
// save area.
module OneHotToBinary8 (
    input [7:0] oneHot,
    output reg [2:0] binary
);
    always @* begin
        case (oneHot)
            8'h01: binary = 0;
            8'h02: binary = 1;
            8'h04: binary = 2;
            8'h08: binary = 3;
            8'h10: binary = 4;
            8'h20: binary = 5;
            8'h40: binary = 6;
            8'h80: binary = 7;
            default: binary = 8;
        endcase
    end
endmodule

