// One-hot-to-integer function, generated by
// $ onehot2integer, part of the SIGASM signal-on-gate
// assembly language.
function integer onehot2integer;
    input [0:7] onehot;
    begin
        case (onehot)
            8'b00000001: onehot2integer = 0;
            8'b00000010: onehot2integer = 1;
            8'b00000100: onehot2integer = 2;
            8'b00001000: onehot2integer = 3;
            8'b00010000: onehot2integer = 4;
            8'b00100000: onehot2integer = 5;
            8'b01000000: onehot2integer = 6;
            8'b10000000: onehot2integer = 7;
            8'b00000011: onehot2integer = 8;
            8'b00000111: onehot2integer = 9;
            default: onehot2integer = -1;
        endcase
    end
endfunction

